CSS = r"""
:root{--bg:#020817;--cyan:#00d9ff;--blue:#087bff;--purple:#a000ff;--green:#00e6a0;--red:#ff2870;--text:#e8f2ff;--muted:#91a9ce}
.gradio-container{max-width:1500px!important;background:radial-gradient(ellipse at 50% 0%,#0a1b42 0%,#020817 58%)!important;color:var(--text)!important;font-family:Inter,Arial,sans-serif!important;padding:14px!important}
body{background:#020817!important}footer{display:none!important}*{box-sizing:border-box}
.app-header{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:15px 20px;margin-bottom:14px;border-bottom:1px solid #0759bd;background:linear-gradient(100deg,#07132d,#020817);border-radius:14px;box-shadow:0 5px 24px #006aff18}
.brand{display:flex;align-items:center;gap:13px}.brand-mark{font-size:38px;filter:drop-shadow(0 0 9px #a000ff)}.brand-title{font-size:clamp(20px,3vw,30px);font-weight:850;color:white}.brand-title span{color:var(--cyan);text-shadow:0 0 12px #00d9ff70}.brand-subtitle{font-size:13px;color:#9db7df;margin-top:3px}
.system-status{display:grid;grid-template-columns:12px auto;align-items:center;column-gap:8px;color:var(--green);font-size:12px;font-weight:700}.system-status small{grid-column:2;color:#91a9ce;font-size:10px;font-weight:500}.status-dot{width:9px;height:9px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green)}
.app-tabs button[role=tab]{color:#b9cbea!important;border-radius:9px!important}.app-tabs button[aria-selected=true]{color:white!important;background:linear-gradient(100deg,#064acb,#09236b)!important;border:1px solid var(--cyan)!important;box-shadow:0 0 15px #087bff50}
.panel{background:linear-gradient(145deg,#07152e,#030b1d)!important;border:1px solid #087bff9c!important;border-radius:15px!important;padding:15px!important;box-shadow:0 0 16px #006aff20;min-width:0}
.section-heading{display:flex;align-items:center;gap:9px;color:#e4f1ff;font-size:15px;font-weight:800;letter-spacing:.45px;margin:2px 0 13px;text-shadow:0 0 9px #087bff45}.heading-icon{color:var(--cyan);font-size:19px}.live-pill{margin-left:auto;color:var(--green);border:1px solid #00e6a080;border-radius:20px;padding:3px 9px;font-size:10px}
.top-grid{align-items:stretch!important}.video-panel{border-color:#087bff!important}.video-input{border-radius:10px;overflow:hidden}.video-input video{max-height:430px;object-fit:contain;background:#01040c}
.status-message{font-size:13px;color:#a9c6ed!important;background:#06132b;border-left:3px solid var(--cyan);padding:9px 12px;border-radius:6px}
.waiting-note{font-size:11px;color:#7995be;line-height:1.5;padding:10px 2px;border-top:1px solid #17325b;margin-top:10px}
.stats-panel input{font-size:23px!important;font-weight:800!important;color:var(--cyan)!important}
button{transition:transform .16s ease,box-shadow .16s ease,border-color .16s ease!important;border-radius:9px!important;min-height:42px}button:hover{transform:translateY(-1px);box-shadow:0 0 16px #087bff55!important;border-color:var(--cyan)!important}
button.primary{background:linear-gradient(100deg,#064cdb,#087bff)!important;border:1px solid var(--cyan)!important;color:white!important}button.stop{background:linear-gradient(100deg,#3a092c,#760b42)!important;border:1px solid var(--red)!important;color:#ff8bad!important}button.secondary{background:#091a3b!important;border:1px solid #174c9c!important;color:#dceaff!important}
input,textarea,select{background:#091a3b!important;color:white!important;border:1px solid #164b91!important;border-radius:8px!important}label{color:#c8dcfa!important}input[type=range]{accent-color:var(--cyan)!important}
.gradio-plot{background:transparent!important;min-width:0!important}.dataframe{overflow-x:auto!important}
@media(max-width:850px){.gradio-container{padding:9px!important}.top-grid{flex-direction:column!important}.top-grid>div{width:100%!important}.stats-panel{min-width:0!important}.app-header{padding:12px}.brand-mark{font-size:30px}}
@media(max-width:600px){.gradio-container{padding:6px!important}.app-header{gap:7px;padding:10px}.brand{gap:8px}.brand-mark{font-size:25px}.brand-title{font-size:18px}.brand-subtitle{font-size:10px}.system-status{font-size:10px}.panel{padding:10px!important;border-radius:11px!important}.section-heading{font-size:13px;margin-bottom:9px}.video-input video{max-height:250px}.stats-panel input{font-size:18px!important}.app-tabs button[role=tab]{font-size:11px!important;padding:8px 7px!important;white-space:nowrap}.gradio-row{flex-wrap:wrap!important}.gradio-row>div{min-width:0!important;flex:1 1 130px!important}.status-message{font-size:12px}}
@media(max-width:360px){.brand-subtitle{display:none}.system-status small{font-size:9px}.app-tabs button[role=tab]{font-size:10px!important;padding:7px 5px!important}}
"""